/**
 * @summary Import keywords from file
 */
export const getImportMonitoringKeywordsUrl = () => {
  return `/api/monitoring/import`;
};

export const importMonitoringKeywords = async (
  importMonitoringKeywordsBody: ImportMonitoringKeywordsBody,
  options?: RequestInit,
): Promise<ImportResponse> => {
  const formData = new FormData();
  if (importMonitoringKeywordsBody.file !== undefined) {
    formData.append(`file`, importMonitoringKeywordsBody.file);
  }
  if (importMonitoringKeywordsBody.tmname !== undefined) {
    formData.append(`tmname`, importMonitoringKeywordsBody.tmname);
  }
  if (importMonitoringKeywordsBody.class !== undefined) {
    formData.append(`class`, importMonitoringKeywordsBody.class);
  }
  if (importMonitoringKeywordsBody.country !== undefined) {
    formData.append(`country`, importMonitoringKeywordsBody.country);
  }
  if (importMonitoringKeywordsBody.client !== undefined) {
    formData.append(`client`, importMonitoringKeywordsBody.client);
  }

  return customFetch<ImportResponse>(getImportMonitoringKeywordsUrl(), {
    ...options,
    method: "POST",
    body: formData,
  });
};

